const n75=node({type:"@n8n/n8n-nodes-langchain.agent",version:3.1,config:{...{"name":"ensaio sem angulo1 — chamada","parameters":{"promptType":"define","text":expr("{{ $json.texto }}"),"options":{"systemMessage":"=Formate o input como se fosse uma newsletter em primeira pessoa. O objetivo é soar com alguém conversando com um amigo inteligente.\n\nPreserve o vocabulário do input, o tamanho dos períodos e o tom de voz.\n\nMétrica principal: VALOR ENTREGUE POR CARACTERES. Seja direto ao ponto e faça o texto progredir, sem ser repetitivo, mas não resuma o input, pois o output deve ser um conteúdo long-form. \n\nNunca use travessões (\"—\").\n\nRetorne apenas o texto.\n\n## Saída\n\nRetorne JSON válido, sem cercas de código ou comentários fora do JSON. Formato: {\"text\":\"todo o texto solicitado, com suas quebras de linha\"}.\n"}},"position":[-11488,12112],"onError":"continueRegularOutput","notes":"Personalize livremente o prompt e o modelo. Não precisa de Output Parser. O Code seguinte estrutura o resultado."},subnodes:{model:n52}},output:[{texto:"Texto exemplo",text:"Texto exemplo",cut:"Texto exemplo",baseText:"Texto exemplo",part:"Parte",angle:"Ângulo",sourceWordCount:300,decision:{accepted:false},error:null,operation:"generate",sourceKind:"recorte",decisionRequest:{}}]});
const n76=node({type:"@n8n/n8n-nodes-langchain.agent",version:3.1,config:{...{"name":"título e subtítulo1 — chamada","parameters":{"promptType":"define","text":expr("{{ $json.texto }}"),"options":{"systemMessage":"=Crie um título curto (até 9 palavras) e um subtítulo (até 20 palavras) para o texto do input, que eu escrevi.\n\nPara o título, tente usar a estrutura dos 4Us: utilidade (benefício claro), urgência (motivo legítimo para agir agora), unicidade (formulação que o leitor ainda não viu) e ultraespecificidade (detalhes concretos).\n\nJá o subtítulo deve acrescentar contexto ao título e fazer um gancho com o início do input.\n\nNão faça sensacionalismo, clickbait e nem prometa coisas que o input não entrega.\n\n## Contrato de retorno para integração\nRetorne {\"title\":\"headline\",\"subtitle\":\"subtítulo\"}.\nRetorne JSON válido, sem cercas de código ou comentários fora do JSON."}},"position":[-10168,12112],"onError":"continueRegularOutput","notes":"Personalize livremente o prompt e o modelo. Não precisa de Output Parser. O Code seguinte estrutura o resultado."},subnodes:{model:n52}},output:[{texto:"Texto exemplo",text:"Texto exemplo",cut:"Texto exemplo",baseText:"Texto exemplo",part:"Parte",angle:"Ângulo",sourceWordCount:300,decision:{accepted:false},error:null,operation:"generate",sourceKind:"recorte",decisionRequest:{}}]});
const n77=node({type:"n8n-nodes-base.code",version:2,config:{...{"name":"Conservar ensaio para título1","parameters":{"jsCode":"// Helpers usados apenas para conservar respostas e contexto deste estágio.\nfunction parseOutput(value) {\n  if (typeof value !== 'string') return value;\n  const text = value.trim().replace(/^\\x60\\x60\\x60(?:json)?\\s*\\n?([\\s\\S]*?)\\n?\\x60\\x60\\x60$/i, '$1').trim();\n  try { return JSON.parse(text); } catch { return text; }\n}\nfunction textOf(value) {\n  return typeof value === 'string' ? value.trim()\n    : typeof value?.text === 'string' ? value.text.trim()\n    : typeof value?.body === 'string' ? value.body.trim() : '';\n}\nfunction contextFrom(name, index) {\n  try { return $(name).itemMatching(index)?.json ?? null; } catch { return null; }\n}\nfunction stageError(message, context, stage) {\n  return {origin: 'diario', referenceId: context.referenceId ?? null, stage, message: String(message?.message ?? message)};\n}\nfunction inputValue(item) {\n  return item?.json && typeof item.json === 'object' ? item.json\n    : item && typeof item === 'object' && ('output' in item || 'error' in item) ? item : {};\n}\nreturn $input.all().map((item, index) => {\n  const value = inputValue(item);\n  const savedContext = contextFrom(\"Contar palavras para conteúdo — Diário\", index);\n  const context = savedContext ?? {};\n  const stageErrors = Array.isArray(context.stageErrors) ? [...context.stageErrors] : [];\n  if (!savedContext) stageErrors.push(stageError('Contexto vinculado ao ensaio indisponível; resposta original conservada.', context, 'contexto do ensaio'));\n  const parsed = parseOutput(value.output);\n  const essayBody = textOf(parsed) || (typeof context.essayBody === 'string' ? context.essayBody : '');\n  let error = value.error ?? null;\n  if (error) stageErrors.push(stageError(error, context, 'ensaio'));\n  if (!essayBody) {\n    error ??= {message: 'Agent não retornou um texto de ensaio utilizável; resposta original conservada.'};\n    if (!value.error) stageErrors.push(stageError(error, context, 'ensaio'));\n  }\n  return {json: {...context, essayBody, texto: essayBody, cut: essayBody, essayOutput: value.output ?? null, stageErrors, error}, pairedItem: {item: index}};\n});"},"position":[-10960,11904]}},output:[{texto:"Texto exemplo",text:"Texto exemplo",cut:"Texto exemplo",baseText:"Texto exemplo",part:"Parte",angle:"Ângulo",sourceWordCount:300,decision:{accepted:false},error:null,operation:"generate",sourceKind:"recorte",decisionRequest:{}}]});
